/**
 * Writes each curated scheme as one override sheet, `schemes/<id>.css`, from its table in
 * `schemes.ts`. The table stays the source, so the contrast rails keep one input; the sheets are
 * generated by `npm run generate:schemes` and `schemeSheets.test.ts` fails when one drifts.
 *
 * A sheet reassigns layers 1 and 2 only (`web/DESIGN.md` §2, "The token layers"):
 *
 *   :root[data-theme="<id>"]        the palette steps the base sheet lacks, and the dark semantics
 *   :root.light[data-theme="<id>"]  the light semantics
 *
 * Both blocks set the same semantic tokens, so a dark value can never leak into light mode.
 */
import { normalizeHex, paletteName } from './palette'
import type { Scheme } from './schemes'

export const GENERATED_NOTE = 'Generated from design/schemes.ts by `npm run generate:schemes`. Edit the table, not this file.'

/** The palette names every scheme sheet uses, assigned after the base sheet's in `SCHEMES` order,
 *  so adding a scheme never renames a value an earlier sheet already uses. */
export function schemePaletteNames(schemes: Scheme[], basePalette: Map<string, string>): Map<string, string> {
  const taken = new Map(basePalette)
  for (const s of schemes) {
    for (const v of Object.values(s.colors)) {
      paletteName(v.dark, taken)
      paletteName(v.light, taken)
    }
  }
  return taken
}

function nameOf(hex: string, names: Map<string, string>): string {
  const value = normalizeHex(hex)
  for (const [name, v] of names) if (v === value) return name
  throw new Error(`no palette name for ${hex}`)
}

const byStep = (a: string, b: string) => a.localeCompare(b, 'en', { numeric: true })

export function schemeSheetCss(scheme: Scheme, names: Map<string, string>, basePalette: Map<string, string>): string {
  const keys = Object.keys(scheme.colors)
  const own = new Set<string>()
  for (const k of keys) {
    for (const hex of [scheme.colors[k].dark, scheme.colors[k].light]) {
      const n = nameOf(hex, names)
      if (!basePalette.has(n)) own.add(n)
    }
  }
  const lines = [
    `/* ${scheme.label}. ${GENERATED_NOTE} */`,
    `:root[data-theme="${scheme.id}"] {`,
  ]
  if (own.size) {
    lines.push('  /* layer 1: the steps the base sheet does not have */')
    for (const n of [...own].sort(byStep)) lines.push(`  ${n}: ${names.get(n)};`)
    lines.push('  /* layer 2, dark */')
  }
  for (const k of keys) lines.push(`  ${k}: var(${nameOf(scheme.colors[k].dark, names)});`)
  lines.push('}', `:root.light[data-theme="${scheme.id}"] {`)
  for (const k of keys) lines.push(`  ${k}: var(${nameOf(scheme.colors[k].light, names)});`)
  lines.push('}', '')
  return lines.join('\n')
}

/** `schemes/index.css`: every sheet, in `SCHEMES` order, imported once after `tokens.css`. */
export function schemeIndexCss(schemes: Scheme[]): string {
  return [
    `/* Every curated scheme's override sheet, loaded after tokens.css. ${GENERATED_NOTE} */`,
    ...schemes.map((s) => `@import "./${s.id}.css";`),
    '',
  ].join('\n')
}
